package com.brasa.restaurant.service;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.enums.Enums.*;import com.brasa.restaurant.exception.ApiExceptions;import com.brasa.restaurant.mapper.ApiMapper;import com.brasa.restaurant.model.*;import com.brasa.restaurant.repository.Repositories.*;import com.brasa.restaurant.security.SecurityUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;@Service public class AdminService{private final CategoriaRepository cats;private final ProdutoRepository products;private final PedidoRepository orders;private final FuncionarioRepository employees;private final EscalaRepository schedules;private final ChamadoRepository calls;private final MesaRepository tables;public AdminService(CategoriaRepository a,ProdutoRepository b,PedidoRepository c,FuncionarioRepository d,EscalaRepository e,ChamadoRepository f,MesaRepository g){cats=a;products=b;orders=c;employees=d;schedules=e;calls=f;tables=g;}private String tenant(){return SecurityUtils.current().restaurantId();}private <T extends BaseEntity>T own(T e,String restaurantId){if(!restaurantId.equals(tenant()))throw new ApiExceptions.Forbidden("Recurso pertence a outro restaurante");return e;}public List<CategoriaDto>categories(){return cats.findByRestauranteIdOrderByOrdemAsc(tenant()).stream().map(ApiMapper::category).toList();}public CategoriaDto saveCategory(String id,CategoriaDto x){Categoria c;if(id==null){c=new Categoria();}else{c=cats.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Categoria não encontrada"));own(c,c.getRestauranteId());}c.setRestauranteId(tenant());c.setNome(x.nome());c.setOrdem(x.ordem());return ApiMapper.category(cats.save(c));}public void deleteCategory(String id){Categoria c=cats.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Categoria não encontrada"));own(c,c.getRestauranteId());cats.delete(c);}public List<ProdutoDto>products(){return products.findByRestauranteIdOrderByNomeAsc(tenant()).stream().map(ApiMapper::product).toList();}public ProdutoDto saveProduct(String id,ProdutoDto x){Produto p=id==null||id.isBlank()?new Produto():products.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Produto não encontrado"));if(p.getId()!=null)own(p,p.getRestauranteId());if(cats.findById(x.categoria_id()).filter(c->c.getRestauranteId().equals(tenant())).isEmpty())throw new ApiExceptions.Business("Categoria inválida");p.setRestauranteId(tenant());p.setCategoriaId(x.categoria_id());p.setNome(x.nome());p.setDescricao(x.descricao());p.setPreco(x.preco());p.setImagemUrl(x.imagem_url());p.setDisponivel(x.disponivel());return ApiMapper.product(products.save(p));}public void deleteProduct(String id){Produto p=products.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Produto não encontrado"));own(p,p.getRestauranteId());products.delete(p);}public List<PedidoResponse>orders(){return orders.findByRestauranteIdOrderByCriadoEmDesc(tenant()).stream().map(ApiMapper::order).toList();}public PedidoResponse changeStatus(String id,StatusPedido status){Pedido p=orders.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Pedido não encontrado"));own(p,p.getRestauranteId());p.setStatus(status);return ApiMapper.order(orders.save(p));}public List<FuncionarioDto>employees(){return employees.findByRestauranteIdOrderByNomeAsc(tenant()).stream().map(ApiMapper::employee).toList();}public FuncionarioDto saveEmployee(FuncionarioDto x){Funcionario f=x.id()==null?new Funcionario():employees.findById(x.id()).orElseThrow();if(f.getId()!=null)own(f,f.getRestauranteId());f.setRestauranteId(tenant());f.setNome(x.nome());f.setCargo(x.cargo());f.setTurno(x.turno());f.setAtivo(x.ativo());return ApiMapper.employee(employees.save(f));}public List<EscalaDto>schedules(LocalDate week){return schedules.findByRestauranteIdAndSemanaReferencia(tenant(),week).stream().map(ApiMapper::schedule).toList();}@Transactional public List<EscalaDto>saveSchedules(List<EscalaDto>list){List<EscalaSemanal>out=new ArrayList<>();for(EscalaDto x:list){if(employees.findById(x.funcionario_id()).filter(f->f.getRestauranteId().equals(tenant())).isEmpty())throw new ApiExceptions.Business("Funcionário inválido");EscalaSemanal e=schedules.findByRestauranteIdAndFuncionarioIdAndSemanaReferencia(tenant(),x.funcionario_id(),x.semana_referencia()).orElse(new EscalaSemanal());e.setRestauranteId(tenant());e.setFuncionarioId(x.funcionario_id());e.setSemanaReferencia(x.semana_referencia());e.setSeg(x.dias().seg());e.setTer(x.dias().ter());e.setQua(x.dias().qua());e.setQui(x.dias().qui());e.setSex(x.dias().sex());e.setSab(x.dias().sab());e.setDom(x.dias().dom());out.add(schedules.save(e));}return out.stream().map(ApiMapper::schedule).toList();}public List<ChamadoResponse>calls(){return calls.findByRestauranteIdAndStatusOrderByCriadoEmAsc(tenant(),StatusChamado.ABERTO).stream().map(ApiMapper::call).toList();}public ChamadoResponse answer(String id){Chamado c=calls.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Chamado não encontrado"));own(c,c.getRestauranteId());c.setStatus(StatusChamado.ATENDIDO);return ApiMapper.call(calls.save(c));}@Transactional public void closeTable(int number){Mesa m=tables.findByRestauranteIdAndNumero(tenant(),number).orElseThrow(()->new ApiExceptions.NotFound("Mesa não encontrada"));orders.findByRestauranteIdAndNumeroMesaAndStatusNotOrderByCriadoEmDesc(tenant(),number,StatusPedido.FECHADO).forEach(p->{p.setStatus(StatusPedido.FECHADO);orders.save(p);});calls.findByRestauranteIdAndNumeroMesaAndStatus(tenant(),number,StatusChamado.ABERTO).forEach(c->{c.setStatus(StatusChamado.FECHADO);calls.save(c);});m.setStatus(StatusMesa.FECHADA);tables.save(m);}}
